import unreal,json
a=next(a for a in unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_all_level_actors() if isinstance(a,unreal.Landscape))
rows=[]
for c in a.get_components_by_class(unreal.LandscapeComponent):
 r={'component':c.get_name()}
 for name in ['WeightmapTextures','WeightmapLayerAllocations','ComponentSizeQuads']:
  try: r[name]=str(c.get_editor_property(name))
  except Exception as e: r[name]=str(e)
 rows.append(r)
print(json.dumps(rows,indent=2))
